import numpy as np
def equation(t, x, v, params):
    w=params[9]
    C=np.cos(w*t)
    return (params[0]+params[1]*x+params[2]*x**3+params[3]*v+params[4]*v**3+params[5]*np.sin(v)
            +(params[6]+params[7]*x+params[8]*v)*C)

from scipy.optimize import minimize_scalar
one=np.ones_like(t)
P=[one,x,v,x*x,v*v,x*v,np.sin(v),x**3]
M=[one,x,v]
def build(w,env):
    cols=list(P)
    for f in [np.cos(w*t),np.sin(w*t)]:
        for g in M: cols.append(f*g*env)
    return np.column_stack(cols)
def fitE(w,env):
    X=build(w,env)
    c,_,_,_=np.linalg.lstsq(X,dv_dt,rcond=None)
    return np.mean((dv_dt-X@c)**2)/np.var(dv_dt),c
for name,env in [('none',one),('t',t),('1/t',1/t),('sqrt t',np.sqrt(t)),('t2',t*t)]:
    r=minimize_scalar(lambda w: fitE(w,env)[0],bounds=(0.3,0.5),method='bounded',options={'xatol':1e-9})
    print(name, round(r.x,5), r.fun)

